css:
@page {
    size: A4;
    margin: 1cm;
}

.urgent {
    color: red;
    font-weight: bold;
    font-size: 20px;
    border: 2px solid red;
    display: inline-block;
    padding: 5px;
    margin-bottom: 10px;
}

.parts-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
    margin-bottom: 15px;
}

.parts-table th, .parts-table td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
}

.parts-table th {
    background-color: #f2f2f2;
    font-weight: bold;
}

.page-break {
    page-break-before: always;
}

@media print {
    .interactive {
        display: none;
    }
}
